package org.sagebionetworks.repo.model;

import org.sagebionetworks.schema.HasEffectiveSchema;
import org.sagebionetworks.schema.adapter.JSONEntity;
import org.sagebionetworks.schema.adapter.JSONObjectAdapter;
import org.sagebionetworks.schema.adapter.JSONObjectAdapterException;

/**
 * Wrapper for a single boolean result, serialized as <code>{"result": true|false}</code>.
 */
public class BooleanResult implements JSONEntity, HasEffectiveSchema {

	// Hand-written rather than generated by schema-to-pojo: its generated hashCode() declares a local
	// named "result", which collides with a property of the same name.
	public static final String EFFECTIVE_SCHEMA = "{\"id\":\"org.sagebionetworks.repo.model.BooleanResult\",\"name\":\"BooleanResult\","
			+ "\"description\":\"Wrapper for a single boolean result.\",\"type\":\"object\","
			+ "\"properties\":{\"result\":{\"type\":\"boolean\",\"description\":\"The boolean result of the request.\"}}}";

	private static final String KEY_RESULT = "result";

	private boolean result;
	
	public BooleanResult() {}

	public BooleanResult(boolean result) {
		super();
		this.result = result;
	}

	/**
	 * @return the result
	 */
	public boolean getResult() {
		return result;
	}

	/**
	 * @param result the result to set
	 */
	public void setResult(boolean result) {
		this.result = result;
	}

	@Override
	public JSONObjectAdapter initializeFromJSONObject(JSONObjectAdapter adapter) throws JSONObjectAdapterException {
		if (adapter == null) {
			throw new IllegalArgumentException("Adapter cannot be null");
		}
		result = !adapter.isNull(KEY_RESULT) && adapter.getBoolean(KEY_RESULT);
		return adapter;
	}

	@Override
	public JSONObjectAdapter writeToJSONObject(JSONObjectAdapter adapter) throws JSONObjectAdapterException {
		if (adapter == null) {
			throw new IllegalArgumentException("Adapter cannot be null");
		}
		adapter.put(KEY_RESULT, result);
		return adapter;
	}

	@Override
	public String getEffectiveSchema() {
		return EFFECTIVE_SCHEMA;
	}

	/* (non-Javadoc)
	 * @see java.lang.Object#hashCode()
	 */
	@Override
	public int hashCode() {
		final int prime = 31;
		int result = 1;
		result = prime * result + (this.result ? 1231 : 1237);
		return result;
	}

	/* (non-Javadoc)
	 * @see java.lang.Object#equals(java.lang.Object)
	 */
	@Override
	public boolean equals(Object obj) {
		if (this == obj)
			return true;
		if (obj == null)
			return false;
		if (!(obj instanceof BooleanResult))
			return false;
		BooleanResult other = (BooleanResult) obj;
		if (result != other.result)
			return false;
		return true;
	}
	
	
}
